<template>
  <section class="page">
    <div class="page-heading"><div><p class="section-label">平台管理</p><h1>订单管理</h1></div><span class="scope-note">查看全平台订单，不修改订单状态</span></div>
    <form class="filter-panel" @submit.prevent="applyFilters">
      <label><span>订单号</span><input v-model.trim="filters.number" type="search" placeholder="输入订单号" /></label>
      <label><span>手机号</span><input v-model.trim="filters.phone" type="search" placeholder="输入收货手机号" /></label>
      <label><span>订单状态</span><select v-model="filters.status"><option value="">全部状态</option><option v-for="item in statusOptions" :key="item.value" :value="item.value">{{ item.label }}</option></select></label>
      <label><span>开始日期</span><input v-model="filters.begin" type="date" /></label>
      <label><span>结束日期</span><input v-model="filters.end" type="date" /></label>
      <div class="filter-actions"><el-button class="ui-action primary-button" native-type="submit" type="primary" :icon="Search">查询</el-button><el-button class="ui-action secondary-button" native-type="button" @click="resetFilters">重置</el-button></div>
    </form>
    <section class="table-panel">
      <div class="table-heading"><h2>平台订单</h2><span v-if="!loading && !errorMessage">共 {{ total }} 单</span></div>
      <div v-if="loading" class="state-panel">正在加载订单...</div>
      <div v-else-if="errorMessage" class="state-panel state-error"><p>{{ errorMessage }}</p><el-button class="ui-action secondary-button" native-type="button" @click="loadOrders" :icon="Refresh">重新加载</el-button></div>
      <div v-else-if="orders.length === 0" class="state-panel"><p>暂无符合条件的订单</p><el-button class="ui-action secondary-button" native-type="button" @click="resetFilters">清除筛选</el-button></div>
      <template v-else>
        <div class="table-scroll"><table><thead><tr><th>订单</th><th>用户</th><th>状态</th><th>商品</th><th>金额</th><th>下单时间</th><th class="action-column">操作</th></tr></thead><tbody><tr v-for="order in orders" :key="order.id"><td><strong>{{ order.number }}</strong><small>{{ order.consignee || '-' }} · {{ order.phone || '-' }}</small></td><td>{{ order.userName || `用户 ${order.userId}` }}</td><td><span class="status" :class="`status-${order.status}`">{{ statusText(order.status) }}</span></td><td>{{ dishCount(order.dishes) }} 份 / {{ merchantCount(order.dishes) }} 个商户</td><td>¥ {{ money(order.amount) }}</td><td>{{ formatDate(order.orderTime) }}</td><td class="action-column"><el-button class="ui-action link-button" native-type="button" @click="openDetail(order.id)" type="primary" link>查看详情</el-button></td></tr></tbody></table></div>
        <div class="pagination"><span>第 {{ page }} / {{ pageCount }} 页</span><el-pagination :current-page="page" :page-size="pageSize" :total="total" :pager-count="5" layout="prev, pager, next" :disabled="loading" @current-change="changePage" /></div>
      </template>
    </section>
    <div v-if="detailVisible" class="drawer-mask" @click.self="closeDetail"><aside class="drawer"><div class="drawer-heading"><div><p>订单详情</p><h2>{{ detailOrder?.number || '-' }}</h2></div><button class="close-button" type="button" @click="closeDetail">×</button></div><div v-if="detailLoading" class="state-panel">正在加载详情...</div><div v-else-if="detailError" class="state-panel state-error"><p>{{ detailError }}</p><el-button class="ui-action secondary-button" native-type="button" @click="loadDetail(detailId)" :icon="Refresh">重新加载</el-button></div><template v-else-if="detailOrder"><div class="detail-summary"><span class="status" :class="`status-${detailOrder.status}`">{{ statusText(detailOrder.status) }}</span><strong>¥ {{ money(detailOrder.amount) }}</strong></div><section v-for="group in merchantGroups(detailOrder.dishes)" :key="group.id" class="merchant-group"><h3>{{ group.name }}</h3><div v-for="dish in group.dishes" :key="dish.id" class="dish-row"><div><strong>{{ dish.name }}</strong><small>{{ dish.dishFlavor || '默认规格' }}</small></div><span>× {{ dish.number }}</span><span>¥ {{ money(Number(dish.amount || 0) * Number(dish.number || 0)) }}</span></div></section><dl class="detail-list"><div><dt>用户</dt><dd>{{ detailOrder.userName || `用户 ${detailOrder.userId}` }}</dd></div><div><dt>收货信息</dt><dd>{{ detailOrder.consignee || '-' }} · {{ detailOrder.phone || '-' }}</dd></div><div><dt>配送地址</dt><dd>{{ detailOrder.address || '-' }}</dd></div><div><dt>配送员</dt><dd>{{ detailOrder.deliveryUserName || '暂未接单' }}</dd></div><div><dt>下单时间</dt><dd>{{ formatDate(detailOrder.orderTime) }}</dd></div><div><dt>支付时间</dt><dd>{{ formatDate(detailOrder.checkoutTime) }}</dd></div><div><dt>预约时间</dt><dd>{{ formatDate(detailOrder.orderDeliveryTime) }}</dd></div><div><dt>订单备注</dt><dd>{{ detailOrder.remark || '无' }}</dd></div><div><dt>商品金额</dt><dd>¥ {{ money(Number(detailOrder.amount || 0) - Number(detailOrder.deliveryFee || 0)) }}</dd></div><div><dt>配送费</dt><dd>¥ {{ money(detailOrder.deliveryFee) }}</dd></div></dl><div class="drawer-actions"><el-button class="ui-action secondary-button" native-type="button" @click="closeDetail">关闭</el-button></div></template></aside></div>
  </section>
</template>

<script setup>
import { Search, Refresh } from '@element-plus/icons-vue'
import { computed, onMounted, reactive, ref } from 'vue'
import { getAdminOrderApi, pageAdminOrdersApi } from '../api/adminOrder.js'
const pageSize = 10, page = ref(1), total = ref(0), orders = ref([]), loading = ref(false), errorMessage = ref('')
const filters = reactive({ number: '', phone: '', status: '', begin: '', end: '' })
const detailVisible = ref(false), detailLoading = ref(false), detailError = ref(''), detailOrder = ref(null), detailId = ref(null)
const statusOptions = [{ value: 1, label: '待支付' }, { value: 2, label: '待接单' }, { value: 3, label: '制作中' }, { value: 4, label: '待取餐' }, { value: 5, label: '配送中' }, { value: 6, label: '待确认收餐' }, { value: 7, label: '已完成' }, { value: 8, label: '已取消' }]
const pageCount = computed(() => Math.max(1, Math.ceil(total.value / pageSize)))
function params() { const value = { page: page.value, pageSize }; Object.entries(filters).forEach(([key, item]) => { if (item !== '') value[key] = item }); return value }
async function loadOrders() { loading.value = true; errorMessage.value = ''; try { const response = await pageAdminOrdersApi(params()); if (response.data?.code !== 200) throw new Error(response.data?.message || '订单加载失败'); total.value = Number(response.data.data?.total || 0); orders.value = response.data.data?.records || [] } catch (error) { orders.value = []; total.value = 0; errorMessage.value = error.response?.data?.message || error.message || '订单加载失败，请稍后重试' } finally { loading.value = false } }
function applyFilters() { page.value = 1; loadOrders() }
function resetFilters() { Object.assign(filters, { number: '', phone: '', status: '', begin: '', end: '' }); page.value = 1; loadOrders() }
function changePage(next) { if (next >= 1 && next <= pageCount.value && next !== page.value) { page.value = next; loadOrders() } }
async function openDetail(id) { detailVisible.value = true; detailId.value = id; await loadDetail(id) }
async function loadDetail(id) { detailLoading.value = true; detailError.value = ''; detailOrder.value = null; try { const response = await getAdminOrderApi(id); if (response.data?.code !== 200) throw new Error(response.data?.message || '详情加载失败'); detailOrder.value = response.data.data } catch (error) { detailError.value = error.response?.data?.message || error.message || '详情加载失败，请稍后重试' } finally { detailLoading.value = false } }
function closeDetail() { detailVisible.value = false }
function statusText(status) { return statusOptions.find(item => item.value === status)?.label || '未知状态' }
function money(value) { return Number(value || 0).toFixed(2) }
function formatDate(value) { return value ? String(value).replace('T', ' ').slice(0, 16) : '-' }
function dishCount(dishes) { return (dishes || []).reduce((sum, dish) => sum + Number(dish.number || 0), 0) }
function merchantCount(dishes) { return new Set((dishes || []).map(dish => dish.merchantId)).size }
function merchantGroups(dishes) { const groups = new Map(); (dishes || []).forEach(dish => { if (!groups.has(dish.merchantId)) groups.set(dish.merchantId, { id: dish.merchantId, name: dish.merchantName || `商户 ${dish.merchantId}`, dishes: [] }); groups.get(dish.merchantId).dishes.push(dish) }); return [...groups.values()] }
onMounted(loadOrders)
</script>

<style scoped>
