right}.link-button{padding:0;border:0;background:transparent;color:#1766a6;cursor:pointer}.state-panel{min-height:190px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:28px;color:#6f8192;font-size:13px}.state-error{color:#b5534e}.pagination{display:flex;align-items:center;justify-content:space-between;padding:15px 20px;color:#6f8192;font-size:12px}.drawer-mask{position:fixed;z-index:40;inset:0;display:flex;justify-content:flex-end;background:rgba(32,54,78,.3)}.drawer{width:min(600px,100%);height:100%;display:flex;flex-direction:column;overflow-y:auto;background:#fff}.drawer-heading{display:flex;align-items:center;justify-content:space-between;padding:20px 24px;border-bottom:1px solid #e4eaf0}.drawer-heading p{margin-bottom:6px;color:#6f8192;font-size:12px}.close-button{border:0;background:transparent;color:#6f8192;font-size:26px;cursor:pointer}.detail-summary{display:flex;justify-content:space-between;padding:18px 24px;border-bottom:1px solid #edf1f4}.merchant-group{margin:18px 24px;border:1px solid #e4eaf0}.merchant-group h3{padding:11px 13px;background:#f7f9fb;color:#40566c;font-size:13px}.dish-row{display:grid;grid-template-columns:minmax(0,1fr) 45px 85px;gap:10px;padding:11px 13px;border-top:1px solid #edf1f4;font-size:12px}.dish-row small{display:block;margin-top:4px;color:#82919e}.dish-row>span:last-child{text-align:right}.detail-list{padding:0 24px 20px}.detail-list>div{display:grid;grid-template-columns:82px 1fr;gap:16px;padding:12px 0;border-bottom:1px solid #edf1f4;font-size:13px}.detail-list dt{color:#82919e}.detail-list dd{margin:0;color:#40566c;word-break:break-word}.drawer-actions{display:flex;justify-content:flex-end;padding:18px 24px;border-top:1px solid #e4eaf0}.drawer-actions button{font:inherit}@media(max-width:700px){.page-heading{align-items:start;flex-direction:column}.filter-panel label{width:100%}.pagination{align-items:start;flex-direction:column;gap:12px}}
</style>
